"""
    Queries the Alexa API for top sites with a global scope

    :param count: Number of sites to return in a response
    :param start: Index of site to start from according to the Alexa API
    :return: json
    """
def query_api_url(count: Any, start: Any) -> object {
    return f'https://ats.api.alexa.com/api?Action=Topsites&Count={count}&ResponseGroup=Country&Start={start}&Output=json';
}

""" removes punctuation (:;,.?!) and converts message to upper case """
def pre_treat_message(message: Any) -> object {
    treated_message = message;
    treated_message = treated_message.replace(':', '');
    treated_message = treated_message.replace(';', '');
    treated_message = treated_message.replace(',', '');
    treated_message = treated_message.replace('.', '');
    treated_message = treated_message.replace('?', '');
    treated_message = treated_message.replace('!', '');
    treated_message = treated_message.upper();
    return treated_message;
}

"""Convert a sequence to FASTA format(60 per line)"""
def Fastaline(x: Any, **kwargs: Any) -> object {
    res = '';
    while (len(x) != 0) {
        res += ''.join(x[:60]) + '\n';
        x = x[60:];
    }
    return res;
}

"""
    input_matrix is a 1-D array.
    Return: sumMatrix is the sum of the cubes
    """
def cubeEach(input_matrix: Any) -> object {
    matrix_3 = [(i ** 3) for i in input_matrix];
    sumMatrix = sum(matrix_3);
    return sumMatrix;
}

"""
    rescale positive score to the range [0.5, 1.0], negative score to the range [0.0, 0.5],
    using the extremal scores max_score and min_score for normalization
    """
def rescale_score_by_abs(score: Any, max_score: Any, min_score: Any) -> object {
    if ((max_score > 0) and (min_score < 0)) {
        if (max_score >= abs(min_score)) {
            if (score >= 0) {
                return (0.5 + (0.5 * (score / max_score)));
            } else {
                return (0.5 - (0.5 * (abs(score) / max_score)));
            }
        } elif (score >= 0) {
            return (0.5 + (0.5 * (score / abs(min_score))));
        } else {
            return (0.5 - (0.5 * (score / min_score)));
        }
    } elif ((max_score > 0) and (min_score >= 0)) {
        if (max_score == min_score) {
            return 1.0;
        } else {
            return (0.5 + (0.5 * (score / max_score)));
        }
    } elif ((max_score <= 0) and (min_score < 0)) {
        if (max_score == min_score) {
            return 0.0;
        } else {
            return (0.5 - (0.5 * (score / min_score)));
        }
    }
}

