"""converts color temperature in Kelvin to RGB values according to
    http://www.vendian.org/mncharity/dir3/blackbody/UnstableURLs/bbr_color.html"""
def kelvin_to_rgb(K: Any) -> object {
    table = {
        4000: (1.0, 0.6636, 0.3583),
        5000: (1.0, 0.7992, 0.6045),
        6000: (1.0, 0.9019, 0.8473),
        7000: (0.9337, 0.915, 1.0),
        8000: (0.7874, 0.8187, 1.0),
        9000: (0.6693, 0.7541, 1.0),
        0: (1, 1, 1)
    };
    rgb = table[K];
    return rgb;
}

"""
    Test if the parameters are anagram of themselves.
    :param word_1: 1st word
    :param word_2: 2nd word
    :return: True if the parameters are anagram, False if not
    """
def is_anagram(word_1: Any, word_2: Any) -> object {
    word_1.lower();
    word_2.lower();
    return (sorted(word_1) == sorted(word_2));
}

