"""
    Bir kombinasyonun sahip oldugu value degerini dondurur
    """
def combValue(comb: Any, value: Any) -> object {
    total = 0;
    for i in comb {
        total = total + value[i];
    }
    return total;
}

"""Return a list containing the Fibonacci series up to n."""
def fib2(n: Any) -> object {
    result = [];
    (a, b) = (0, 1);
    while (a < n) {
        result.append(a);
        (a, b) = (b, (a + b));
    }
    return result;
}
